contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public entry that tests initialize idempotence: first call succeeds, second reverts
    function run(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) public payable {
        // no precondition on parameters; feeRate checked by contract (will revert if >5000)

        bool firstReverted;
        bool secondReverted;

        // First attempt: try to initialize once. It may revert (e.g., invalid feeRate), record result.
        c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }

        // Second attempt: try initialize again with same args; per contract it must revert with AlreadyInitialized() if first succeeded.
        c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }

        // General rule: if the first initialize call succeeded (did NOT revert), then the second must revert.
        // If the first call already reverted (invalid inputs), we cannot require behavior about the second, so allow both to revert or succeed.
        assert(firstReverted || (!firstReverted && secondReverted));
    }

    receive() external payable {}
}

