// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PrivatePool c;

    function setUp() public {
        c = new PrivatePool(address(this), address(this), address(this));
    }

    function _run(address _baseToken, address _nft, uint128 _virtualBaseTokenReserves, uint128 _virtualNftReserves, uint56 _changeFee, uint16 _feeRate, bytes32 _merkleRoot, bool _useStolenNftOracle, bool _payRoyalties) internal {
        bool firstReverted;
        bool secondReverted;
        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }
        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }
        assertTrue(firstReverted || (!firstReverted && secondReverted));
    }

    function testFuzz_run(address _baseToken, address _nft, uint128 _virtualBaseTokenReserves, uint128 _virtualNftReserves, uint56 _changeFee, uint16 _feeRate, bytes32 _merkleRoot, bool _useStolenNftOracle, bool _payRoyalties) public {
        vm.assume(_baseToken.code.length == 0 && uint160(_baseToken) > 0xffff && _baseToken != address(this) && _baseToken != address(c) && _baseToken != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && _baseToken != 0x000000000000000000636F6e736F6c652e6c6f67 && _baseToken != 0x4e59b44847b379578588920cA78FbF26c0B4956C && _baseToken != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(_nft.code.length == 0 && uint160(_nft) > 0xffff && _nft != address(this) && _nft != address(c) && _nft != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && _nft != 0x000000000000000000636F6e736F6c652e6c6f67 && _nft != 0x4e59b44847b379578588920cA78FbF26c0B4956C && _nft != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(_baseToken, _nft, _virtualBaseTokenReserves, _virtualNftReserves, _changeFee, _feeRate, _merkleRoot, _useStolenNftOracle, _payRoyalties);
    }

    receive() external payable {}
}
